class Solution {
public:
    const long long MOD = 1e9 + 7;
    long long pw(long long b, long long e) {
        long long r = 1; b %= MOD;
        while (e) { if (e & 1) r = r * b % MOD; b = b * b % MOD; e >>= 1; }
        return r;
    }
    int numberOfSequence(int n, vector<int>& sick) {
        int T = n - sick.size();
        vector<long long> fac(T + 1, 1), inv(T + 1, 1);
        for (int i = 1; i <= T; i++) fac[i] = fac[i - 1] * i % MOD;
        inv[T] = pw(fac[T], MOD - 2);
        for (int i = T; i >= 1; i--) inv[i - 1] = inv[i] * i % MOD;
        vector<int> b;
        b.push_back(-1);
        for (int x : sick) b.push_back(x);
        b.push_back(n);
        long long ans = fac[T];
        for (int t = 0; t + 1 < (int)b.size(); t++) {
            long long L = b[t + 1] - b[t] - 1;
            if (L <= 0) continue;
            long long ways = (t == 0 || t + 2 == (int)b.size()) ? 1 : pw(2, L - 1);
            ans = ans * ways % MOD * inv[L] % MOD;
        }
        return (int)ans;
    }
};

