class Solution {
    private static final long MOD = 1_000_000_007L;
    private long pw(long b, long e) {
        long r = 1; b %= MOD;
        while (e > 0) { if ((e & 1) == 1) r = r * b % MOD; b = b * b % MOD; e >>= 1; }
        return r;
    }
    public int numberOfSequence(int n, int[] sick) {
        int T = n - sick.length;
        long[] fac = new long[T + 1], inv = new long[T + 1];
        fac[0] = 1;
        for (int i = 1; i <= T; i++) fac[i] = fac[i - 1] * i % MOD;
        inv[T] = pw(fac[T], MOD - 2);
        for (int i = T; i >= 1; i--) inv[i - 1] = inv[i] * i % MOD;
        long ans = fac[T];
        int prev = -1;
        for (int t = 0; t <= sick.length; t++) {
            int cur = (t < sick.length) ? sick[t] : n;
            long L = cur - prev - 1;
            if (L > 0) {
                boolean boundary = (prev == -1) || (cur == n);
                long ways = boundary ? 1 : pw(2, L - 1);
                ans = ans * ways % MOD * inv[(int) L] % MOD;
            }
            prev = cur;
        }
        return (int) ans;
    }
};

