var numberOfSequence = function(n, sick) {
    const MOD = 1e9 + 7n, N = BigInt(n - sick.length);
    const pw = (b, e) => { let r = 1n; b %= MOD; while (e > 0n) { if (e & 1n) r = r * b % MOD; b = b * b % MOD; e >>= 1n; } return r; };
    const fac = [1n];
    for (let i = 1n; i <= N; i++) fac.push(fac[fac.length - 1] * i % MOD);
    const inv = new Array(fac.length);
    inv[N] = pw(fac[N], MOD - 2n);
    for (let i = N; i >= 1n; i--) inv[i - 1n] = inv[i] * i % MOD;
    const b = [-1, ...sick, n];
    let ans = fac[N];
    for (let t = 0; t + 1 < b.length; t++) {
        const L = BigInt(b[t + 1] - b[t] - 1);
        if (L <= 0n) continue;
        const ways = (t === 0 || t + 2 === b.length) ? 1n : pw(2n, L - 1n);
        ans = ans * ways % MOD * inv[L] % MOD;
    }
    return Number(ans);
};
